def closestValue(nums, target):
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    if lo == 0:
        return nums[0]
    if lo == len(nums):
        return nums[-1]
    left, right = nums[lo - 1], nums[lo]
    return left if target - left <= right - target else right
